import"./AdminLayout.astro_astro_type_script_index_0_lang.FBYA5ckr.js";document.querySelectorAll(".toggle-pin-btn").forEach(e=>{e.addEventListener("click",async()=>{const t=e.getAttribute("data-id");try{(await fetch(`/api/admin/announcements/${t}/pin`,{method:"PATCH"})).ok&&window.location.reload()}catch{alert("Error al actualizar el estado fijado")}})});document.querySelectorAll(".toggle-archive-btn").forEach(e=>{e.addEventListener("click",async()=>{const t=e.getAttribute("data-id");try{(await fetch(`/api/admin/announcements/${t}/archive`,{method:"PATCH"})).ok&&window.location.reload()}catch{alert("Error al archivar comunicado")}})});document.querySelectorAll(".delete-ann-btn").forEach(e=>{e.addEventListener("click",async()=>{const t=e.getAttribute("data-id"),a=e.getAttribute("data-title")||"este comunicado";if(confirm(`¿Está seguro de eliminar el comunicado "${a}"? Se borrarán también sus registros de confirmación.`))try{(await fetch(`/api/admin/announcements/${t}`,{method:"DELETE"})).ok&&window.location.reload()}catch{alert("Error al eliminar el comunicado")}})});
